create unique index if not exists idx_analyses_anonymous_idempotency
  on analyses (anonymous_session_id, idempotency_key)
  where anonymous_session_id is not null and idempotency_key is not null;

create table if not exists rateLimit (
  id text primary key not null,
  key text not null unique,
  count integer not null,
  lastRequest integer not null
);

create unique index if not exists idx_analyses_workspace_idempotency
  on analyses (workspace_id, idempotency_key)
  where workspace_id is not null and idempotency_key is not null;

create unique index if not exists idx_batches_one_active_per_workspace
  on batches (workspace_id)
  where status in ('queued', 'processing');

create index if not exists idx_batches_asset_retention_expires
  on batches (asset_retention_expires_at)
  where asset_retention_expires_at is not null;

create unique index if not exists idx_products_workspace_sku_key
  on products (workspace_id, sku_key)
  where sku_key is not null;

create unique index if not exists idx_product_reference_current
  on product_reference_versions (product_id)
  where status = 'current';

create index if not exists idx_batches_product_created
  on batches (product_id, created_at desc)
  where product_id is not null;

create unique index idx_product_reference_current_role
  on product_reference_versions (product_id, reference_role)
  where status = 'current';

CREATE TRIGGER product_guard_update BEFORE UPDATE ON products
WHEN OLD.current_profile_version_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM product_write_guards g WHERE g.workspace_id=OLD.workspace_id AND g.product_id=OLD.id AND g.ok=1
) BEGIN SELECT RAISE(ABORT,'legacy_write_blocked'); END;

CREATE TRIGGER product_pointer_scope BEFORE UPDATE OF current_profile_version_id ON products
WHEN NEW.current_profile_version_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM product_profile_versions v WHERE v.id=NEW.current_profile_version_id AND v.workspace_id=NEW.workspace_id AND v.product_id=NEW.id
) BEGIN SELECT RAISE(ABORT,'profile_pointer_scope'); END;

CREATE TABLE batch_product_snapshots (
  batch_id TEXT PRIMARY KEY REFERENCES batches(id) ON DELETE CASCADE,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL,product_revision INTEGER NOT NULL,profile_version_id TEXT NOT NULL,reference_version_id TEXT NOT NULL,
  snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),snapshot_sha256 TEXT NOT NULL CHECK(length(snapshot_sha256)=64),bound_at TEXT NOT NULL
);

CREATE TABLE review_write_guards (
 token TEXT PRIMARY KEY, analysis_id TEXT NOT NULL, workspace_id TEXT NOT NULL,
 ok INTEGER NOT NULL CHECK(ok=1)
);

CREATE TABLE review_heads (
 analysis_id TEXT PRIMARY KEY REFERENCES analyses(id) ON DELETE RESTRICT,
 workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
 revision INTEGER NOT NULL CHECK(revision>0),
 latest_event_id TEXT NOT NULL REFERENCES review_events(id) ON DELETE RESTRICT
);
